import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const router = express.Router();
const upload = multer({ storage: multer.memoryStorage() });

interface KeywordAnalysis {
  matched: string[];
  missing: string[];
  score: number;
}

function analyzeResume(resumeText: string, jobDescription: string): KeywordAnalysis {
  const cleanText = (text: string) => text.toLowerCase().match(/\b[a-z]{3,}\b/g) || [];
  const resumeWords = new Set(cleanText(resumeText));
  const jobWords = Array.from(new Set(cleanText(jobDescription)));

  const matched: string[] = [];
  const missing: string[] = [];

  jobWords.forEach((word) => {
    if (resumeWords.has(word)) {
      matched.push(word);
    } else {
      missing.push(word);
    }
  });

  const score = jobWords.length > 0 ? Math.round((matched.length / jobWords.length) * 100) : 0;
  return { matched, missing, score };
}

router.post('/scan', upload.single('resume'), async (req: Request, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'PDF resume file is required' });
      return;
    }
    const { jobDescription } = req.body;
    if (!jobDescription) {
      res.status(400).json({ error: 'Job description is required' });
      return;
    }

    const pdfData = await pdfParse(req.file.buffer);
    const analysis = analyzeResume(pdfData.text, jobDescription);

    res.json({
      success: true,
      fileName: req.file.originalname,
      ...analysis,
    });
  } catch (error) {
    res.status(500).json({ error: 'Failed to parse PDF and calculate keyword match' });
  }
});

export default router;

import React, { useState } from 'react';

interface ScanResult {
  score: number;
  matched: string[];
  missing: string[];
  fileName: string;
}

export const AnimatedMatchDashboard: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [jobDescription, setJobDescription] = useState('');
  const [result, setResult] = useState<ScanResult | null>(null);
  const [loading, setLoading] = useState(false);

  const handleScan = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file || !jobDescription) return;

    setLoading(true);
    const formData = new FormData();
    formData.append('resume', file);
    formData.append('jobDescription', jobDescription);

    try {
      const res = await fetch('/api/scan', { method: 'POST', body: formData });
      const data = await res.json();
      if (data.success) setResult(data);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6 bg-slate-900 text-white rounded-xl shadow-2xl">
      <h1 className="text-2xl font-bold mb-6 text-indigo-400">AI Resume Keyword Scanner</h1>
      <form onSubmit={handleScan} className="space-y-4 mb-8">
        <input
          type="file"
          accept=".pdf"
          onChange={(e) => setFile(e.target.files?.[0] || null)}
          className="block w-full text-sm text-slate-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-indigo-600 file:text-white hover:file:bg-indigo-700 cursor-pointer"
        />
        <textarea
          rows={5}
          placeholder="Paste Job Description here..."
          value={jobDescription}
          onChange={(e) => setJobDescription(e.target.value)}
          className="w-full p-3 rounded-lg bg-slate-800 border border-slate-700 text-white focus:outline-none focus:border-indigo-500"
        />
        <button
          type="submit"
          disabled={loading || !file}
          className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 font-semibold rounded-lg transition"
        >
          {loading ? 'Analyzing Resume...' : 'Scan Match Score'}
        </button>
      </form>

      {result && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="flex flex-col items-center justify-center bg-slate-800 p-6 rounded-xl border border-slate-700">
            <div className="relative flex items-center justify-center">
              <span className="text-4xl font-extrabold text-indigo-400">{result.score}%</span>
            </div>
            <span className="mt-2 text-sm text-slate-400">Match Score</span>
          </div>
          <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 md:col-span-2">
            <h3 className="font-semibold mb-3 text-emerald-400">Matched Keywords</h3>
            <div className="flex flex-wrap gap-2 mb-4">
              {result.matched.map((word) => (
                <span key={word} className="px-3 py-1 bg-emerald-950 text-emerald-300 border border-emerald-800 rounded-full text-xs font-medium">{word}</span>
              ))}
            </div>
            <h3 className="font-semibold mb-3 text-rose-400">Missing Keywords</h3>
            <div className="flex flex-wrap gap-2">
              {result.missing.map((word) => (
                <span key={word} className="px-3 py-1 bg-rose-950 text-rose-300 border border-rose-800 rounded-full text-xs font-medium">{word}</span>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
